return {["fb204_01"]={["down"]=[[fb204_04]],["dsc"]=[[庙会中心以北的大街。相对与正中心来说这里的行人少了不少，但仍旧有不少小贩吆喝着。不远处有几个孩子在嬉戏，两旁都是苏式白墙青砖房，房子上都张灯结彩，热闹非凡。往南边一直走便能到达庙会中心了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_01]],["name"]=[[北大街]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb204_02"]={["down"]=[[fb204_07]],["dsc"]=[[这里是两条街交汇之处，也是人流滚滚十分热闹的场所。只见街边一溜的摊贩，贩卖者各种东西，小吃、玩物，物品繁多，应有尽有。街上灯火辉煌，行人来来往往，到处传来说笑声。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_02]],["name"]=[[大街口]],["permission"]=1,["right"]=[[fb204_03]],["stepMusic"]=[[jiaobu]]},["fb204_03"]={["dsc"]=[[北大街的内街。由于是链接两条大街的内街，摊贩少了不少。街道两边是一些寻常的商铺，三两行人在里面买东西。能感觉到难得的清静与悠闲。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_03]],["left"]=[[fb204_02]],["name"]=[[北内大街]],["permission"]=1,["right"]=[[fb204_04]],["stepMusic"]=[[jiaobu]]},["fb204_04"]={["down"]=[[fb204_08]],["dsc"]=[[四条北街的交汇之处。处处人声鼎沸，人人脸上洋溢着喜悦之色。一名老者拄着拐杖在一旁休息，倒显得与场景格格不入。这里可以通往北街的各个地方。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_04]],["left"]=[[fb204_03]],["name"]=[[十字街口]],["permission"]=1,["right"]=[[fb204_05]],["stepMusic"]=[[jiaobu]],["up"]=[[fb204_01]]},["fb204_05"]={["down"]=[[fb204_09]],["dsc"]=[[北大街的内街。由于是链接两条大街的内街，摊贩少了不少。街道两边是一些寻常的商铺，三两行人在里面买东西。能感觉到难得的清静与悠闲。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_05]],["left"]=[[fb204_04]],["name"]=[[北内大街]],["permission"]=1,["right"]=[[fb204_06]],["stepMusic"]=[[jiaobu]]},["fb204_06"]={["down"]=[[fb204_10]],["dsc"]=[[这里是两条街交汇之处，也是人流滚滚十分热闹的场所。只见街边一溜的摊贩，贩卖者各种东西，小吃、玩物，物品繁多，应有尽有。街上灯火辉煌，行人来来往往，到处传来说笑声。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_06]],["left"]=[[fb204_05]],["name"]=[[大街口]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb204_07"]={["down"]=[[fb204_11]],["dsc"]=[[西大街的内街。由于是链接两条大街的内街，摊贩少了不少。街道两边是一些寻常的商铺，三两行人在里面买东西。能感觉到难得的清静与悠闲。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb204_07]],["name"]=[[西内大街]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb204_02]]},["fb204_08"]={["down"]=[[fb204_12]],["dsc"]=[[庙会中心以北的大街。相对与正中心来说这里的行人少了不少，但仍旧有不少小贩吆喝着。两旁都是苏式白墙青砖房，房子上都张灯结彩，热闹非凡。往南边一直走便能到达庙会中心了。]],["fightBackground"]=[[城镇室外]],["id"]=[